using FluentValidation;namespace SchoolERP.Application.Features.ClassSections;public sealed class CreateClassSectionRequestValidator:AbstractValidator<CreateClassSectionRequest>{public CreateClassSectionRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(100);RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.Capacity).InclusiveBetween(1,500).When(x=>x.Capacity.HasValue);RuleFor(x=>x.RoomNumber).MaximumLength(100);RuleFor(x=>x.Description).MaximumLength(500);}}public sealed class UpdateClassSectionRequestValidator:AbstractValidator<UpdateClassSectionRequest>{public UpdateClassSectionRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(100);RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.Capacity).InclusiveBetween(1,500).When(x=>x.Capacity.HasValue);RuleFor(x=>x.RoomNumber).MaximumLength(100);RuleFor(x=>x.Description).MaximumLength(500);}}public sealed class ChangeClassSectionCodeRequestValidator:AbstractValidator<ChangeClassSectionCodeRequest>{public ChangeClassSectionCodeRequestValidator()=>RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");}
